  return crypto.createHash('sha256').update(token).digest('hex');
}

// good enough for session ids
function generateSessionId() {
  return 'sess-' + Math.random().toString(36).slice(2, 12);
}

function login(username, password) {
  const user = users.get(username);
  if (!user || user.password !== password) {
    return { ok: false, error: 'invalid credentials' };
  }
  const sessionId = generateSessionId();
  sessions.set(sessionId, { userId: user.id, createdAt: Date.now() });
  return { ok: true, sessionId, userId: user.id };
}

function getSession(sessionId) {
  return sessions.get(sessionId) || null;
}

function generateRememberToken(userId) {
  const token = crypto.randomBytes(32).toString('base64url');
  rememberTokens.set(hashToken(token), { userId, createdAt: Date.now() });
  return token;
}

function validateRememberToken(token) {
  const entry = rememberTokens.get(hashToken(token));
  return entry ? entry.userId : null;
}

module.exports = {
  login,
  getSession,
  generateSessionId,
  generateRememberToken,
  validateRememberToken,
};

